-- ============================================================
-- Baseball History: "On This Day" feature
-- Run this in the Supabase SQL Editor
-- ============================================================

CREATE TABLE IF NOT EXISTS baseball_history (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  month INTEGER NOT NULL CHECK (month BETWEEN 1 AND 12),
  day INTEGER NOT NULL CHECK (day BETWEEN 1 AND 31),
  year INTEGER,
  fact TEXT NOT NULL,
  category TEXT CHECK (category IN ('record','world_series','no_hitter','debut','death','hall_of_fame','milestone','postseason')),
  player_name TEXT,
  team TEXT
);

ALTER TABLE baseball_history ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Anyone can read baseball history"
  ON baseball_history FOR SELECT TO anon, authenticated USING (true);

